package kr.yoonseul.core;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class TimerScreen extends Screen{private final Screen parent;private long end;private int seconds=300;public TimerScreen(Screen p){super(Component.literal("윤슬 타이머"));parent=p;}protected void init(){int x=(width-420)/2,y=(height-240)/2;addRenderableWidget(Button.builder(Component.literal("- 1분"),b->{seconds=Math.max(60,seconds-60);rebuildWidgets();}).bounds(x+20,y+70,110,24).build());addRenderableWidget(Button.builder(Component.literal("+ 1분"),b->{seconds+=60;rebuildWidgets();}).bounds(x+145,y+70,110,24).build());addRenderableWidget(Button.builder(Component.literal("시작"),b->end=System.currentTimeMillis()+seconds*1000L).bounds(x+270,y+70,130,24).build());addRenderableWidget(Button.builder(Component.literal("초기화"),b->{end=0;seconds=300;}).bounds(x+20,y+130,180,24).build());addRenderableWidget(Button.builder(Component.literal("돌아가기"),b->minecraft.gui.setScreen(parent)).bounds(x+220,y+130,180,24).build());}private long remain(){return end==0?seconds:Math.max(0,(end-System.currentTimeMillis()+999)/1000);}public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float d){int x=(width-420)/2,y=(height-240)/2;g.fill(0,0,width,height,0xAA080B10);g.fill(x,y,x+420,y+210,0xF01A2029);long r=remain();g.text(font,"윤슬 타이머",x+20,y+20,0xFFFFFFFF,false);g.text(font,String.format("%02d:%02d",r/60,r%60),x+184,y+42,0xFF9BE7D7,false);if(end>0&&r==0)g.text(font,"시간이 끝났어요!",x+160,y+176,0xFFFFCC66,false);super.extractRenderState(g,mx,my,d);}public boolean isPauseScreen(){return false;}}
